"use client";

import { useEffect, useMemo, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent } from "react";
import { Activity, AlertTriangle, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, CandlestickChart, Check, CheckCircle2, ChevronDown, Copy, Crosshair, Grip, Layers3, LayoutTemplate, LineChart, Link2, Maximize2, Minus, MoreHorizontal, Pencil, Plus, RotateCcw, Ruler, Save, ShieldCheck, SlidersHorizontal, Trash2, Unlink, Volume2, X } from "lucide-react";
import { toast } from "sonner";
import { useAuth } from "@/components/auth/AuthProvider";
import { usePortfolioBooks } from "@/components/portfolio/PortfolioBooksProvider";
import { useWorkspacePrototype } from "@/components/workspace/WorkspacePrototypeProvider";
import { ContextBar, Status } from "@/components/workspace/WorkspaceUI";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { useTradingWorkspace } from "@/hooks/useTradingWorkspace";
import InteractiveMarketChart, { type InteractiveChartMode, type InteractiveChartPoint } from "@/components/market/InteractiveMarketChart";
import { calculatePositionSizing, type TradeDirection } from "@/lib/trading/positionSizing";
import { DEFAULT_PAPER_POLICY, evaluatePaperPolicy } from "@/lib/trading/paperPolicy";
import { SessionPaperTradingService, type PaperOrder } from "@/lib/trading/paperTradingService";
import type { TradingWorkspaceTemplate } from "@/lib/trading/workspacePresets";
import type { TradingWorkspace, WorkspaceWidgetInstance, WorkspaceWidgetType } from "@/lib/trading/workspaceSchema";
import { workspaceWidgetRegistry } from "./widgetRegistry";
import styles from "./TradingWorkspace.module.css";

const QUOTES = { AMD: { price: 170, change: 1.24 }, NVDA: { price: 132, change: -0.68 }, AAPL: { price: 226, change: 0.42 } } as const;
const DEFAULT_WATCHLIST = Object.keys(QUOTES) as Array<keyof typeof QUOTES>;
const TABS = ["Positions", "Orders", "Fills", "Signals", "Journal", "Portfolio Risk"] as const;
type ActivityTab = typeof TABS[number];
type PlanState = { direction: TradeDirection; orderType: "market" | "limit" | "stop"; timeInForce: "day" | "gtc"; entry: string; stop: string; target: string; riskBudget: string; thesis: string };
const DEFAULT_PLAN: PlanState = { direction: "long", orderType: "limit", timeInForce: "day", entry: "170", stop: "164", target: "182", riskBudget: "600", thesis: "" };
const WORKSPACE_TEMPLATES: Array<{ id: TradingWorkspaceTemplate; name: string; description: string }> = [
  { id: "paper_trading", name: "Paper Trading", description: "Plan, validate, and review a simulated trade." },
  { id: "stock_trading", name: "Stock trading", description: "Chart, size, and monitor simulated stock positions." },
  { id: "options_trading", name: "Options trading", description: "Compare a chart, chain, positions, and recent paper orders." },
  { id: "advanced_options", name: "Advanced options trading", description: "Give the options chain more room beside market context." },
  { id: "chart_spotlight", name: "Chart spotlight", description: "Give price action the full center stage." },
  { id: "positions_analysis", name: "Positions analysis", description: "Inspect simulated positions and plan the next decision." },
  { id: "positions_monitor", name: "Positions monitoring", description: "Track paper positions across four independent charts." },
  { id: "watchlist_monitor", name: "Watchlist monitoring", description: "Track one linked watchlist symbol across four timeframes." },
  { id: "market_monitor", name: "Market monitoring", description: "Compare four independently linked charts beside a watchlist." },
];

export default function TradingWorkspaceShell() {
  const auth = useAuth();
  const legacy = useWorkspacePrototype();
  const { summary } = usePortfolioBooks();
  const workspaceState = useTradingWorkspace();
  const { workspace } = workspaceState;
  const [plan, setPlan] = useState<PlanState>(DEFAULT_PLAN);
  const [timeframe, setTimeframe] = useState("1h");
  const [activeTab, setActiveTab] = useState<ActivityTab>("Positions");
  const [watchlistSymbols, setWatchlistSymbols] = useState<Array<keyof typeof QUOTES>>(DEFAULT_WATCHLIST);
  const [selectorOpen, setSelectorOpen] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [orders, setOrders] = useState<PaperOrder[]>([]);
  const [deskLoaded, setDeskLoaded] = useState(false);
  const orderService = useMemo(() => new SessionPaperTradingService(`quanfora.paper-orders.${auth.user.is_guest ? "guest" : `user:${auth.user.id}`}`), [auth.user.id, auth.user.is_guest]);
  useEffect(() => { void orderService.listOrders().then(setOrders); }, [orderService]);
  const deskStorageKey = `quanfora.trade-desk.${auth.user.is_guest ? "guest" : `user:${auth.user.id}`}`;
  useEffect(() => { try { const stored = JSON.parse(window.sessionStorage.getItem(deskStorageKey) ?? "null") as { plan?: Partial<PlanState>; activeTab?: ActivityTab; timeframe?: string; watchlistSymbols?: string[] } | null; if (stored?.plan) setPlan({ ...DEFAULT_PLAN, ...stored.plan }); if (stored?.activeTab && TABS.includes(stored.activeTab)) setActiveTab(stored.activeTab); if (stored?.timeframe) setTimeframe(stored.timeframe); if (stored?.watchlistSymbols) setWatchlistSymbols(stored.watchlistSymbols.filter((symbol): symbol is keyof typeof QUOTES => symbol in QUOTES)); } catch {} setDeskLoaded(true); }, [deskStorageKey]);
  useEffect(() => { if (!deskLoaded) return; try { window.sessionStorage.setItem(deskStorageKey, JSON.stringify({ plan, activeTab, timeframe, watchlistSymbols })); } catch {} }, [activeTab, deskLoaded, deskStorageKey, plan, timeframe, watchlistSymbols]);
  useEffect(() => { const onEscape = (event: KeyboardEvent) => { if (event.key !== "Escape") return; if (selectorOpen) setSelectorOpen(false); else if (workspaceState.isEditing) workspaceState.cancelEdit(); }; window.addEventListener("keydown", onEscape); return () => window.removeEventListener("keydown", onEscape); }, [selectorOpen, workspaceState]);

  const sizing = useMemo(() => calculatePositionSizing({ ...plan, accountEquity: 100_000, existingOpenRisk: 2_400, buyingPower: 20_000 }), [plan]);
  const policy = useMemo(() => evaluatePaperPolicy(sizing, DEFAULT_PAPER_POLICY), [sizing]);
  const setSymbol = (symbol: keyof typeof QUOTES) => { const price = QUOTES[symbol].price; workspaceState.setSelectedSymbol(symbol); setPlan((current) => ({ ...current, entry: String(price), stop: String(price - 6), target: String(price + 12) })); };
  const removeWatchlistSymbol = (symbol: keyof typeof QUOTES) => {
    const next = watchlistSymbols.filter((item) => item !== symbol);
    setWatchlistSymbols(next);
    if (workspace.selectedSymbol === symbol && next[0]) setSymbol(next[0]);
  };
  const submitOrder = async () => {
    const order = await orderService.submitOrder({ symbol: workspace.selectedSymbol, side: plan.direction === "long" ? "buy" : "sell", quantity: sizing.quantity, orderType: plan.orderType, timeInForce: plan.timeInForce, entry: Number(plan.entry), stop: Number(plan.stop), target: Number(plan.target), maximumLoss: sizing.maximumLoss, thesis: plan.thesis.trim() || undefined });
    setOrders((current) => [...current, order]);
    legacy.previewPaperOrder(); legacy.fillPaperOrder({ symbol: order.symbol, entry: order.entry, stop: order.stop, target: order.target, riskBudget: Number(plan.riskBudget), buyingPower: 20_000, currentPortfolioHeat: 2.4 }, { riskPerShare: sizing.riskPerShare, quantity: sizing.quantity, capitalRequired: sizing.capitalRequired, maximumLoss: sizing.maximumLoss, rewardToRisk: sizing.rewardRiskRatio ?? 0, resultingPortfolioHeat: sizing.portfolioHeatAfter ?? 0, policyPassed: policy.status !== "failed", issues: policy.blockingReasons });
    setActiveTab("Orders"); toast.success("Paper order submitted", { description: `${order.quantity} ${order.symbol} shares were added to this session.` });
  };

  const renderWidget = (widget: WorkspaceWidgetInstance) => {
    const widgetTimeframe = typeof widget.settings.timeframe === "string" ? widget.settings.timeframe : timeframe;
    const widgetSymbol = widget.linkedToWorkspaceSymbol ? workspace.selectedSymbol : typeof widget.settings.symbol === "string" ? widget.settings.symbol : workspace.selectedSymbol;
    const props = { symbol: widgetSymbol, plan, setPlan, sizing, policy, timeframe: widgetTimeframe, setTimeframe: (value: string) => { setTimeframe(value); if (widget.settings.timeframe !== undefined) workspaceState.setWidgetSetting(widget.instanceId, "timeframe", value); }, activeTab, setActiveTab, orders, summary };
    switch (widget.type) {
      case "watchlist": return <WatchlistWidget symbol={workspace.selectedSymbol} symbols={watchlistSymbols} onSelect={setSymbol} onRemove={removeWatchlistSymbol} />;
      case "active_signals": return <ActiveSignalsWidget symbol={widgetSymbol} />;
      case "price_chart": return <PriceChartWidget {...props} />;
      case "trade_plan": return <TradePlanWidget {...props} />;
      case "policy_check": return <PolicyCheckWidget policy={policy} />;
      case "trading_activity": return <TradingActivityWidget {...props} />;
      case "account": return <AccountWidget sizing={sizing} />;
      case "options_chain": return <OptionsChainWidget symbol={widgetSymbol} />;
      case "recent_orders": return <RecentOrdersWidget orders={orders} />;
      case "positions": return <PositionsWidget orders={orders} />;
    }
  };
  const visibleWidgets = workspace.widgets.filter((widget) => widget.isVisible);
  const addOrRestoreWidget = (type: WorkspaceWidgetType) => {
    if (!workspaceState.isEditing) workspaceState.enterEdit();
    workspaceState.hiddenTypes.has(type) ? workspaceState.restoreWidget(type) : workspaceState.addWidget(type);
  };

  return <main className="min-h-full bg-[var(--background)] px-3 py-4 text-[var(--text-primary)] lg:px-6">
    <div className="mx-auto max-w-[1700px]">
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--theme-border)] pb-3">
        <div><p className="text-[11px] font-semibold uppercase text-[var(--text-subtle)]">Trading workspace</p><h1 className="mt-1 font-heading text-2xl font-semibold">Paper Trading Desk</h1><p className="mt-1 text-xs text-[var(--text-muted)]">Plan, size, validate, and review a simulated trade before submitting it to the paper journal.</p></div>
        <span className="inline-flex h-9 items-center gap-2 rounded-lg border border-sky-400/35 bg-sky-400/10 px-3 text-xs font-semibold text-sky-300"><span className="size-2 rounded-full bg-sky-300" /> Paper · illustrative</span>
      </header>
      <ContextBar />
      <div className="relative my-3 flex flex-wrap items-center gap-2 border-y border-[var(--theme-border)] bg-[var(--surface-card)] px-3 py-2">
        <Button type="button" variant="outline" aria-expanded={selectorOpen} onClick={() => setSelectorOpen((open) => !open)} className="rounded-lg text-xs">{workspace.name}<ChevronDown className="size-3.5" /></Button>
        <Status tone="neutral">{workspace.presetType === "paper_trading" ? "Recommended preset" : "Custom layout"}</Status>
        <span className="ml-auto inline-flex items-center gap-1.5 text-xs text-[var(--text-muted)]"><Link2 className="size-3.5" /> Linked to {workspace.selectedSymbol}</span>
        <span className="text-xs text-[var(--text-subtle)]" aria-live="polite">{workspaceState.saveState === "saving" ? "Saving…" : workspaceState.saveState === "unsaved" ? "Unsaved changes" : "Saved"}</span>
        <div className="hidden items-center gap-2 xl:flex"><PresetMenu onSelect={workspaceState.createWorkspace} /><WidgetMenu widgets={workspace.widgets} onChoose={addOrRestoreWidget} /></div>
        {!workspaceState.isEditing ? <Button type="button" variant="outline" onClick={workspaceState.enterEdit} className="hidden rounded-lg text-xs xl:inline-flex"><Pencil className="size-3.5" /> Edit layout</Button> : <>
          <Button type="button" variant="ghost" onClick={workspaceState.cancelEdit} className="rounded-lg text-xs">Cancel</Button><Button type="button" variant="ghost" onClick={() => setResetOpen(true)} className="rounded-lg text-xs"><RotateCcw className="size-3.5" /> Reset</Button><Button type="button" onClick={() => void workspaceState.save()} className="theme-solid-action rounded-lg text-xs"><Save className="size-3.5" /> Save layout</Button>
        </>}
        <DropdownMenu><DropdownMenuTrigger render={<Button type="button" variant="ghost" size="icon" aria-label="Workspace actions" className="rounded-lg" />}><MoreHorizontal className="size-4" /></DropdownMenuTrigger><DropdownMenuContent side="bottom" align="end" className="w-64 rounded-xl"><DropdownMenuItem onClick={workspaceState.createEmptyWorkspace}><Plus className="size-4" /> New empty workspace</DropdownMenuItem><DropdownMenuItem onClick={workspaceState.duplicateWorkspace}><Copy className="size-4" /> Duplicate current layout</DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem onClick={() => setResetOpen(true)}><RotateCcw className="size-4" /> Reset to Paper Trading</DropdownMenuItem>{workspace.presetType === "custom" && <DropdownMenuItem onClick={() => setDeleteOpen(true)} className="text-[var(--color-red-negative)]"><Trash2 className="size-4" /> Delete workspace</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu>
        {selectorOpen && <WorkspaceSelector workspaces={workspaceState.workspaces} activeId={workspace.id} onSelect={(id) => { workspaceState.selectWorkspace(id); setSelectorOpen(false); }} onClose={() => setSelectorOpen(false)} onCreate={() => { workspaceState.createEmptyWorkspace(); setSelectorOpen(false); }} />}
      </div>
      {visibleWidgets.length ? <div data-workspace-canvas className={`${styles.canvas} ${workspaceState.isEditing ? styles.editing : ""}`}>
        {visibleWidgets.map((widget) => <WidgetFrame key={widget.instanceId} widget={widget} editing={workspaceState.isEditing} onHide={() => workspaceState.hideWidget(widget.instanceId)} onDuplicate={() => workspaceState.duplicateWidget(widget.instanceId)} onLink={() => workspaceState.setWidgetLinked(widget.instanceId, !widget.linkedToWorkspaceSymbol)} resolveMove={(dx, dy) => workspaceState.resolvePlacement(widget.instanceId, dx, dy)} resolveResize={(dw, dh) => workspaceState.resolvePlacement(widget.instanceId, 0, 0, dw, dh)} onMove={(dx, dy) => workspaceState.moveWidget(widget.instanceId, dx, dy)} onResize={(dw, dh) => workspaceState.resizeWidget(widget.instanceId, dw, dh)}>{renderWidget(widget)}</WidgetFrame>)}
      </div> : <EmptyTradingWorkspace onCreate={workspaceState.createWorkspace} onAdd={addOrRestoreWidget} />}
    </div>
    <AlertDialog open={resetOpen} onOpenChange={setResetOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Reset Paper Trading workspace?</AlertDialogTitle><AlertDialogDescription>This restores the current built-in preset. Your paper orders remain separate and will not be deleted.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Keep layout</AlertDialogCancel><AlertDialogAction onClick={() => { workspaceState.reset(); setResetOpen(false); }}>Reset to preset</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={deleteOpen} onOpenChange={setDeleteOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Delete {workspace.name}?</AlertDialogTitle><AlertDialogDescription>This removes the custom workspace layout from this session. Paper orders and journal records will not be deleted.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Keep workspace</AlertDialogCancel><AlertDialogAction className="bg-[var(--color-red-negative)] text-white" onClick={() => { workspaceState.deleteWorkspace(); setDeleteOpen(false); }}>Delete workspace</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <PaperOrderReview plan={plan} sizing={sizing} policy={policy} symbol={workspace.selectedSymbol} onSubmit={submitOrder} />
  </main>;
}

function WorkspaceSelector({ workspaces, activeId, onSelect, onClose, onCreate }: { workspaces: TradingWorkspace[]; activeId: string; onSelect: (id: string) => void; onClose: () => void; onCreate: () => void }) {
  const custom = workspaces.filter((item) => item.presetType === "custom");
  return <div role="menu" aria-label="Workspace selector" className="absolute left-3 top-12 z-30 w-80 rounded-xl border border-[var(--theme-border-strong)] bg-[var(--surface-popover)] p-2 shadow-[var(--shadow-popover)]">
    <div className="flex items-center justify-between px-2 py-1"><p className="text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Trading workspaces</p><button aria-label="Close workspace selector" onClick={onClose} className="grid size-8 place-items-center rounded-lg hover:bg-[var(--surface-card-hover)]"><X className="size-4" /></button></div>
    <button role="menuitem" type="button" onClick={() => onSelect("paper-trading")} className="flex w-full items-start justify-between rounded-lg p-3 text-left text-xs hover:bg-[var(--surface-card-hover)]"><span><strong className="block">Paper Trading Desk</strong><span className="mt-1 block text-[var(--text-muted)]">Recommended risk-aware planning layout.</span></span>{activeId === "paper-trading" && <Check className="size-4 text-indigo-primary" />}</button>
    <p className="mt-2 border-t border-[var(--theme-border)] px-2 pb-1 pt-3 text-[10px] font-semibold uppercase text-[var(--text-subtle)]">My layouts</p>
    {custom.length ? custom.map((item) => <button key={item.id} role="menuitem" type="button" onClick={() => onSelect(item.id)} className="flex w-full items-center justify-between rounded-lg px-3 py-2.5 text-left text-xs hover:bg-[var(--surface-card-hover)]"><span className="truncate">{item.name}</span>{activeId === item.id && <Check className="size-4 shrink-0 text-indigo-primary" />}</button>) : <p className="px-3 py-2 text-xs text-[var(--text-muted)]">No custom trading layouts yet.</p>}
    <Button type="button" variant="outline" onClick={onCreate} className="mt-2 w-full rounded-lg text-xs"><Plus className="size-4" /> New trading workspace</Button>
  </div>;
}

type WidgetDelta = { x: number; y: number };
function WidgetFrame({ widget, editing, onHide, onDuplicate, onLink, resolveMove, resolveResize, onMove, onResize, children }: { widget: WorkspaceWidgetInstance; editing: boolean; onHide: () => void; onDuplicate: () => void; onLink: () => void; resolveMove: (dx: number, dy: number) => WidgetDelta | null; resolveResize: (dw: number, dh: number) => WidgetDelta | null; onMove: (dx: number, dy: number) => void; onResize: (dw: number, dh: number) => void; children: React.ReactNode }) {
  const registration = workspaceWidgetRegistry[widget.type];
  const resizeStart = useRef<{ x: number; y: number; columnPitch: number; rowPitch: number; pointerId: number } | null>(null);
  const dragStart = useRef<{ x: number; y: number; columnPitch: number; rowPitch: number; pointerId: number } | null>(null);
  const dragDelta = useRef<WidgetDelta>({ x: 0, y: 0 });
  const resizeDelta = useRef<WidgetDelta>({ x: 0, y: 0 });
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [resizePreview, setResizePreview] = useState({ x: 0, y: 0 });
  const getPitch = (target: HTMLElement) => { const canvas = target.closest<HTMLElement>("[data-workspace-canvas]"); if (!canvas) return null; const rect = canvas.getBoundingClientRect(); const computed = getComputedStyle(canvas); const columnGap = Number.parseFloat(computed.columnGap) || 0; const rowGap = Number.parseFloat(computed.rowGap) || 0; return { columnPitch: (rect.width - columnGap * 11) / 12 + columnGap, rowPitch: 48 + rowGap }; };
  const startResize = (event: ReactPointerEvent<HTMLButtonElement>) => { const pitch = getPitch(event.currentTarget); if (!pitch) return; resizeStart.current = { x: event.clientX, y: event.clientY, pointerId: event.pointerId, ...pitch }; resizeDelta.current = { x: 0, y: 0 }; event.currentTarget.setPointerCapture(event.pointerId); event.preventDefault(); };
  const resize = (event: ReactPointerEvent<HTMLButtonElement>) => { const start = resizeStart.current; if (!start || start.pointerId !== event.pointerId) return; const safe = resolveResize(Math.round((event.clientX - start.x) / start.columnPitch), Math.round((event.clientY - start.y) / start.rowPitch)); if (!safe) return; resizeDelta.current = safe; setResizePreview(safe); };
  const finishResize = (event: ReactPointerEvent<HTMLButtonElement>) => { const start = resizeStart.current; if (!start || start.pointerId !== event.pointerId) return; const safe = resizeDelta.current; resizeStart.current = null; resizeDelta.current = { x: 0, y: 0 }; setResizePreview({ x: 0, y: 0 }); if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId); if (safe.x || safe.y) onResize(safe.x, safe.y); };
  const cancelResize = () => { resizeStart.current = null; resizeDelta.current = { x: 0, y: 0 }; setResizePreview({ x: 0, y: 0 }); };
  const startDrag = (event: ReactPointerEvent<HTMLButtonElement>) => { const pitch = getPitch(event.currentTarget); if (!pitch) return; dragStart.current = { x: event.clientX, y: event.clientY, pointerId: event.pointerId, ...pitch }; dragDelta.current = { x: 0, y: 0 }; event.currentTarget.setPointerCapture(event.pointerId); event.preventDefault(); };
  const drag = (event: ReactPointerEvent<HTMLButtonElement>) => { const start = dragStart.current; if (!start || start.pointerId !== event.pointerId) return; const safe = resolveMove(Math.round((event.clientX - start.x) / start.columnPitch), Math.round((event.clientY - start.y) / start.rowPitch)); if (!safe) return; dragDelta.current = safe; setDragOffset({ x: safe.x * start.columnPitch, y: safe.y * start.rowPitch }); };
  const finishDrag = (event: ReactPointerEvent<HTMLButtonElement>) => { const start = dragStart.current; if (!start || start.pointerId !== event.pointerId) return; const safe = dragDelta.current; dragStart.current = null; dragDelta.current = { x: 0, y: 0 }; setDragOffset({ x: 0, y: 0 }); if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId); if (safe.x || safe.y) onMove(safe.x, safe.y); };
  const cancelDrag = () => { dragStart.current = null; dragDelta.current = { x: 0, y: 0 }; setDragOffset({ x: 0, y: 0 }); };
  const style = { "--widget-column": `${widget.position.x + 1} / span ${widget.position.width + resizePreview.x}`, "--widget-row": `${widget.position.y + 1} / span ${widget.position.height + resizePreview.y}`, transform: dragOffset.x || dragOffset.y ? `translate(${dragOffset.x}px, ${dragOffset.y}px)` : undefined, zIndex: dragOffset.x || dragOffset.y ? 20 : undefined } as CSSProperties;
  return <section data-widget-type={widget.type} className={`${styles.widget} relative flex min-h-[210px] flex-col overflow-hidden rounded-lg border bg-[var(--surface-card)] ${editing ? "border-indigo-primary/60" : "border-[var(--theme-border)]"}`} style={style}>
    <header className={`flex h-11 shrink-0 items-center gap-2 border-b border-[var(--theme-border)] px-3 ${editing ? "bg-[var(--surface-control)]" : ""}`}>
      {editing && <button type="button" aria-label={`Move ${registration.title}`} title="Drag to move widget" onPointerDown={startDrag} onPointerMove={drag} onPointerUp={finishDrag} onPointerCancel={cancelDrag} className="grid size-8 touch-none cursor-grab place-items-center rounded-lg hover:bg-[var(--surface-card-hover)] active:cursor-grabbing"><Grip className="size-4 text-[var(--text-muted)]" /></button>}<h2 className="truncate text-xs font-semibold">{widget.title ?? registration.title}</h2>{registration.supportsSymbolLink && !widget.linkedToWorkspaceSymbol && <span className="text-[10px] text-amber-300">Unlinked</span>}
      {editing && <div className="ml-auto flex items-center gap-1">{registration.supportsSymbolLink && <button type="button" title={widget.linkedToWorkspaceSymbol ? "Unlink ticker" : "Link ticker"} onClick={onLink} className="grid size-8 place-items-center rounded-lg hover:bg-[var(--surface-card-hover)]">{widget.linkedToWorkspaceSymbol ? <Unlink className="size-3.5" /> : <Link2 className="size-3.5" />}</button>}{registration.allowDuplicate && <button type="button" title="Duplicate widget" onClick={onDuplicate} className="grid size-8 place-items-center rounded-lg hover:bg-[var(--surface-card-hover)]"><Copy className="size-3.5" /></button>}<button type="button" title="Hide widget" onClick={onHide} className="grid size-8 place-items-center rounded-lg hover:bg-[var(--surface-card-hover)]"><X className="size-3.5" /></button></div>}
    </header>
    <div className="min-h-0 flex-1 overflow-auto">{children}</div>
    {editing && <><div className="absolute bottom-2 left-2 flex gap-1 rounded-lg border border-[var(--theme-border)] bg-[var(--surface-popover)] p-1"><button aria-label="Move left" title="Move left" onClick={() => onMove(-1, 0)} className="grid size-7 place-items-center rounded-md hover:bg-[var(--surface-card-hover)]"><ArrowLeft className="size-3.5" /></button><button aria-label="Move right" title="Move right" onClick={() => onMove(1, 0)} className="grid size-7 place-items-center rounded-md hover:bg-[var(--surface-card-hover)]"><ArrowRight className="size-3.5" /></button><button aria-label="Move up" title="Move up" onClick={() => onMove(0, -1)} className="grid size-7 place-items-center rounded-md hover:bg-[var(--surface-card-hover)]"><ArrowUp className="size-3.5" /></button><button aria-label="Move down" title="Move down" onClick={() => onMove(0, 1)} className="grid size-7 place-items-center rounded-md hover:bg-[var(--surface-card-hover)]"><ArrowDown className="size-3.5" /></button></div><button type="button" aria-label={`Resize ${registration.title}`} title="Drag to resize widget" onPointerDown={startResize} onPointerMove={resize} onPointerUp={finishResize} onPointerCancel={cancelResize} className="absolute bottom-1 right-1 size-8 touch-none cursor-nwse-resize rounded-tl-lg border-b-2 border-r-2 border-indigo-primary bg-[var(--surface-control)]" /></>}
  </section>;
}

function WatchlistWidget({ symbol, symbols, onSelect, onRemove }: { symbol: string; symbols: Array<keyof typeof QUOTES>; onSelect: (symbol: keyof typeof QUOTES) => void; onRemove: (symbol: keyof typeof QUOTES) => void }) {
  if (!symbols.length) return <div className="p-3"><Empty text="Your watchlist is empty. Reset the Paper Trading preset to restore the illustrative symbols." /></div>;
  return <div role="listbox" aria-label="Paper watchlist">{symbols.map((ticker) => { const quote = QUOTES[ticker]; return <div key={ticker} className={`group flex items-center border-b border-[var(--theme-border)] ${symbol === ticker ? "border-l-2 border-l-indigo-primary bg-[var(--surface-selected)]" : "hover:bg-[var(--surface-card-hover)]"}`}><button type="button" role="option" aria-selected={symbol === ticker} onClick={() => onSelect(ticker)} className="flex min-w-0 flex-1 items-center justify-between px-3 py-3 text-left"><span><strong className="block text-xs">{ticker}</strong><span className="text-[10px] text-[var(--text-muted)]">NASDAQ · Equity</span></span><span className="text-right tabular-nums"><strong className="block text-xs">${quote.price.toFixed(2)}</strong><span className={`text-[10px] ${quote.change >= 0 ? "text-emerald-400" : "text-rose-400"}`}>{quote.change >= 0 ? "▲ Gain" : "▼ Loss"} {Math.abs(quote.change).toFixed(2)}%</span></span></button><button type="button" aria-label={`Remove ${ticker} from watchlist`} title={`Remove ${ticker}`} onClick={() => onRemove(ticker)} className="mr-2 grid size-7 shrink-0 place-items-center rounded-md text-[var(--text-subtle)] opacity-0 outline-none hover:bg-[var(--surface-card-hover)] hover:text-[var(--text-primary)] focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-indigo-primary/50 group-hover:opacity-100"><X className="size-3.5" /></button></div>; })}</div>;
}
function ActiveSignalsWidget({ symbol }: { symbol: string }) { return <div className="p-3"><div className="flex gap-2"><Activity className="mt-0.5 size-4 text-sky-300" /><div><strong className="text-xs">Momentum setup</strong><p className="mt-1 text-[11px] text-[var(--text-muted)]">Bullish · 1h · Updated now</p><p className="mt-2 text-xs leading-5 text-[var(--text-muted)]">{symbol} remains above the short-term trend while illustrative volume expands.</p><p className="mt-2 text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Informational · No order submitted</p></div></div></div>; }

function AccountWidget({ sizing }: { sizing: ReturnType<typeof calculatePositionSizing> }) { return <div className="p-3"><p className="text-[10px] font-semibold uppercase text-sky-300">Paper · Illustrative</p><p className="mt-2 text-2xl font-semibold tabular-nums">$100,000.00</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">Paper account equity</p><div className="mt-4 grid grid-cols-2 gap-3 border-t border-[var(--theme-border)] pt-3"><Result label="Buying power" value="$20,000.00" /><Result label="Open risk" value="$2,400.00" /><Result label="Planned capital" value={money(sizing.capitalRequired)} /><Result label="Heat after" value={sizing.portfolioHeatAfter == null ? "Unavailable" : `${sizing.portfolioHeatAfter.toFixed(2)}%`} /></div></div>; }

function OptionsChainWidget({ symbol }: { symbol: string }) { const anchor = QUOTES[symbol as keyof typeof QUOTES]?.price ?? 170; const strikes = [-10, -5, 0, 5, 10].map((offset, index) => { const strike = Math.round((anchor + offset) / 5) * 5; const distance = Math.abs(strike - anchor); return { strike, callBid: Math.max(0.08, 6.2 - distance * 0.38).toFixed(2), callAsk: Math.max(0.12, 6.45 - distance * 0.36).toFixed(2), putBid: Math.max(0.08, 5.8 - distance * 0.35).toFixed(2), putAsk: Math.max(0.12, 6.05 - distance * 0.33).toFixed(2), iv: `${(28 + index * 1.8).toFixed(1)}%`, openInterest: 420 + index * 317 }; }); return <div><div className="flex items-center justify-between border-b border-[var(--theme-border)] px-3 py-2"><div><strong className="text-xs">{symbol} options</strong><p className="text-[10px] text-[var(--text-muted)]">30 days · Illustrative chain</p></div><span className="text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Calls · Puts</span></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-right text-[10px] tabular-nums"><thead className="text-[var(--text-subtle)]"><tr>{["Call bid", "Call ask", "IV", "Open int.", "Strike", "Put bid", "Put ask"].map((label) => <th key={label} className="border-b border-[var(--theme-border)] px-2 py-2 font-semibold">{label}</th>)}</tr></thead><tbody>{strikes.map((row) => <tr key={row.strike} className={Math.abs(row.strike - anchor) < 3 ? "bg-[var(--surface-selected)]" : ""}><td className="border-b border-[var(--theme-border)] px-2 py-2 text-rose-300">${row.callBid}</td><td className="border-b border-[var(--theme-border)] px-2 py-2 text-emerald-300">${row.callAsk}</td><td className="border-b border-[var(--theme-border)] px-2 py-2">{row.iv}</td><td className="border-b border-[var(--theme-border)] px-2 py-2">{row.openInterest.toLocaleString()}</td><td className="border-b border-[var(--theme-border)] px-3 py-2 font-semibold text-[var(--text-primary)]">${row.strike}</td><td className="border-b border-[var(--theme-border)] px-2 py-2 text-rose-300">${row.putBid}</td><td className="border-b border-[var(--theme-border)] px-2 py-2 text-emerald-300">${row.putAsk}</td></tr>)}</tbody></table></div><p className="px-3 py-2 text-[10px] text-[var(--text-subtle)]">Illustrative quotes are for planning only. No options order can be executed.</p></div>; }

function RecentOrdersWidget({ orders }: { orders: PaperOrder[] }) { if (!orders.length) return <div className="p-3"><Empty text="No paper orders have been submitted in this session." /></div>; return <div className="divide-y divide-[var(--theme-border)]">{orders.slice(-6).reverse().map((order) => <div key={order.id} className="grid grid-cols-[1fr_auto] gap-2 px-3 py-2.5"><div className="min-w-0"><strong className="text-xs">{order.symbol} · {order.quantity}</strong><p className="mt-1 truncate text-[10px] capitalize text-[var(--text-muted)]">{order.side} · {order.orderType} · {order.timeInForce.toUpperCase()}</p></div><span className="text-[10px] font-semibold capitalize text-emerald-300">{order.status}</span></div>)}</div>; }

function PositionsWidget({ orders }: { orders: PaperOrder[] }) { const positions = orders.filter((order) => order.status === "filled"); if (!positions.length) return <div className="p-3"><Empty text="No filled simulated positions in this session." /></div>; return <div className="overflow-x-auto"><table className="w-full min-w-[300px] text-left text-[10px] tabular-nums"><thead className="text-[var(--text-subtle)]"><tr>{["Symbol", "Qty", "Entry", "Max risk"].map((label) => <th key={label} className="border-b border-[var(--theme-border)] px-3 py-2">{label}</th>)}</tr></thead><tbody>{positions.slice(-8).reverse().map((order) => <tr key={order.id}><td className="border-b border-[var(--theme-border)] px-3 py-2 font-semibold">{order.symbol}</td><td className="border-b border-[var(--theme-border)] px-3 py-2">{order.side === "sell" ? "−" : "+"}{order.quantity}</td><td className="border-b border-[var(--theme-border)] px-3 py-2">{money(order.entry)}</td><td className="border-b border-[var(--theme-border)] px-3 py-2">{money(order.maximumLoss)}</td></tr>)}</tbody></table></div>; }

function PriceChartWidget({ symbol, plan, timeframe, setTimeframe }: { symbol: string; plan: PlanState; timeframe: string; setTimeframe: (value: string) => void }) {
  const [mode, setMode] = useState<InteractiveChartMode>("candle");
  const [showVolume, setShowVolume] = useState(true);
  const [showSma, setShowSma] = useState(true);
  const [activeTool, setActiveTool] = useState<"crosshair" | "measure">("crosshair");
  const [showLevels, setShowLevels] = useState(true);
  const [fitKey, setFitKey] = useState(0);
  const data = useMemo(() => createDeskMarketData(symbol, timeframe, Number(plan.entry || 0), Number(plan.stop || 0), Number(plan.target || 0)), [plan.entry, plan.stop, plan.target, symbol, timeframe]);
  const quote = data.at(-1)?.price ?? Number(plan.entry || 0);
  const previous = data.at(-2)?.price ?? quote;
  const change = previous ? ((quote - previous) / previous) * 100 : 0;
  return <div className="relative flex h-full min-h-[400px] flex-col">
    <div className="flex min-h-11 flex-wrap items-center gap-2 border-b border-[var(--theme-border)] px-3 py-1.5"><span className="size-2 rounded-sm bg-indigo-primary" /><div><strong className="text-sm">{symbol}</strong><span className="ml-2 text-xs tabular-nums text-[var(--text-muted)]">${quote.toFixed(2)}</span><span className={`ml-2 text-xs ${change >= 0 ? "text-emerald-400" : "text-rose-400"}`}>{change >= 0 ? "▲" : "▼"} {Math.abs(change).toFixed(2)}%</span></div><div className="ml-auto flex items-center gap-1"><ChartTool label="Chart type" active={false} onClick={() => setMode((current) => current === "candle" ? "line" : current === "line" ? "area" : current === "area" ? "bar" : "candle")} icon={mode === "candle" ? CandlestickChart : LineChart} /><ChartTool label="Indicators" active={showSma} onClick={() => setShowSma((value) => !value)} icon={SlidersHorizontal} /><ChartTool label="Volume" active={showVolume} onClick={() => setShowVolume((value) => !value)} icon={Volume2} /><ChartTool label="Fit chart" active={false} onClick={() => setFitKey((value) => value + 1)} icon={Maximize2} /></div></div>
    <div className="flex min-h-0 flex-1">
      <div className="flex w-10 shrink-0 flex-col items-center gap-1 border-r border-[var(--theme-border)] py-2"><ChartTool side="right" label="Crosshair" active={activeTool === "crosshair"} onClick={() => setActiveTool("crosshair")} icon={Crosshair} /><ChartTool side="right" label="Measure range" active={activeTool === "measure"} onClick={() => setActiveTool("measure")} icon={Ruler} /><ChartTool side="right" label="Trade levels" active={showLevels} onClick={() => setShowLevels((value) => !value)} icon={Minus} /><ChartTool side="right" label="Indicator layers" active={showSma} onClick={() => setShowSma((value) => !value)} icon={Layers3} /></div>
      <div className={`relative min-w-0 flex-1 ${activeTool === "measure" ? "cursor-crosshair" : ""}`}><InteractiveMarketChart data={data} mode={mode} color="var(--color-cyan-secondary)" positiveColor="var(--color-green-positive)" negativeColor="var(--color-red-negative)" volume={showVolume} fitKey={fitKey} measurementEnabled={activeTool === "measure"} rangeKey={`${symbol}-${timeframe}`} overlayLines={[...(showLevels ? [{ key: "entryLevel", color: "var(--text-primary)", lineWidth: 1 as const }, { key: "stopLevel", color: "var(--color-red-negative)", lineWidth: 1 as const }, { key: "targetLevel", color: "var(--color-green-positive)", lineWidth: 1 as const }] : []), ...(showSma ? [{ key: "sma20", color: "var(--color-indigo-primary)", lineWidth: 2 as const }] : [])]} axisFormatter={(value) => `$${value.toFixed(2)}`} timeFormatter={(label) => { const date = new Date(label); return timeframe === "1D" ? date.toLocaleDateString([], { month: "short", day: "numeric" }) : date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }} tooltip={(point) => <ChartTooltip point={point} symbol={symbol} />} tooltipClassName="border border-[var(--theme-border-strong)] bg-[var(--surface-popover)] p-2 text-[10px] shadow-[var(--shadow-popover)]" /></div>
    </div>
    <div className="flex shrink-0 flex-wrap items-center gap-2 border-t border-[var(--theme-border)] px-2 py-1.5"><div className="flex rounded-lg bg-[var(--surface-control)] p-0.5" role="group" aria-label="Chart timeframe">{["5m", "15m", "1h", "1D"].map((option) => <button key={option} aria-pressed={timeframe === option} onClick={() => setTimeframe(option)} className={`h-7 rounded-md px-2 text-[10px] font-semibold ${timeframe === option ? "bg-[var(--surface-selected)]" : "text-[var(--text-muted)]"}`}>{option}</button>)}</div><span className="ml-auto text-[10px] text-[var(--text-subtle)]">Drag across chart to measure · Ctrl + wheel to zoom · Double-click to fit</span></div>
    <div className="pointer-events-none absolute left-12 top-12 flex flex-wrap gap-2 border border-[var(--theme-border)] bg-[var(--surface-card)]/90 p-1.5 text-[10px] tabular-nums">{showLevels && <><span>— Entry ${Number(plan.entry || 0).toFixed(2)}</span><span className="text-rose-400">⋯ Stop ${Number(plan.stop || 0).toFixed(2)}</span><span className="text-emerald-400">- - Target ${Number(plan.target || 0).toFixed(2)}</span></>}{showSma && <span className="text-indigo-300">— SMA 20</span>}</div>
  </div>;
}
function ChartTool({ label, active, onClick, icon: Icon, side = "bottom" }: { label: string; active: boolean; onClick: () => void; icon: typeof Crosshair; side?: "bottom" | "right" }) { return <button type="button" aria-label={label} aria-pressed={active} onClick={onClick} className={`group relative grid size-9 place-items-center rounded-lg border text-[var(--text-muted)] outline-none hover:bg-[var(--surface-card-hover)] hover:text-[var(--text-primary)] focus-visible:ring-2 focus-visible:ring-indigo-primary/50 ${active ? "border-indigo-primary bg-[var(--surface-selected)] text-[var(--text-primary)]" : "border-transparent"}`}><Icon className="size-4" /><span role="tooltip" className={`pointer-events-none absolute z-50 hidden whitespace-nowrap rounded-lg border border-[var(--theme-border-strong)] bg-[var(--surface-popover)] px-2 py-1.5 text-[10px] font-medium text-[var(--text-primary)] shadow-[var(--shadow-popover)] group-hover:block group-focus:block ${side === "right" ? "left-full top-1/2 ml-2 -translate-y-1/2" : "right-0 top-full mt-2"}`}>{label}</span></button>; }
function ChartTooltip({ point, symbol }: { point: DeskMarketPoint; symbol: string }) { const legend = [{ label: `${symbol} close`, value: point.price, color: "var(--text-primary)" }, { label: "SMA 20", value: point.sma20, color: "var(--color-indigo-primary)" }, { label: "Entry", value: point.entryLevel, color: "var(--text-primary)" }, { label: "Stop", value: point.stopLevel, color: "var(--color-red-negative)" }, { label: "Target", value: point.targetLevel, color: "var(--color-green-positive)" }]; return <div className="min-w-52 tabular-nums"><strong>{new Date(point.label).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}</strong><div className="mt-1 grid grid-cols-2 gap-x-4 text-[var(--text-muted)]"><span>O {point.open?.toFixed(2)}</span><span>H {point.high?.toFixed(2)}</span><span>L {point.low?.toFixed(2)}</span><span>C {point.price.toFixed(2)}</span></div><div className="mt-2 grid grid-cols-2 gap-x-4 gap-y-1 border-t border-[var(--theme-border)] pt-2 text-[10px] text-[var(--text-muted)]">{legend.map((item) => <span key={item.label} className="flex items-center gap-1.5"><LegendDot color={item.color} /><span>{item.label} {item.value.toFixed(2)}</span></span>)}<span className="col-span-2 flex items-center gap-1.5"><LegendDot color="var(--chart-volume)" />Volume {Math.round(point.volume ?? 0).toLocaleString()}</span></div></div>; }
function LegendDot({ color }: { color: string }) { return <span aria-hidden className="inline-block size-2 shrink-0 rounded-full border border-[var(--theme-border-strong)]" style={{ backgroundColor: color }} />; }
type DeskMarketPoint = InteractiveChartPoint & { entryLevel: number; stopLevel: number; targetLevel: number; sma20: number };
function createDeskMarketData(symbol: string, timeframe: string, anchor: number, stop: number, target: number): DeskMarketPoint[] { const count = 96; const symbolSeed = [...symbol].reduce((sum, char) => sum + char.charCodeAt(0), 0); const interval = timeframe === "5m" ? 5 : timeframe === "15m" ? 15 : timeframe === "1h" ? 60 : 1_440; const start = Date.UTC(2026, 6, 7, 9, 30); const endWave = Math.sin((count - 1 + symbolSeed) / 5) * 1.7 + Math.sin((count - 1 + symbolSeed) / 13) * 0.9; const points: DeskMarketPoint[] = []; for (let index = 0; index < count; index += 1) { const drift = (index - count + 1) * 0.025; const wave = Math.sin((index + symbolSeed) / 5) * 1.7 + Math.sin((index + symbolSeed) / 13) * 0.9; const close = Number((anchor + drift + wave - endWave).toFixed(2)); const open = Number((close - Math.sin(index * 1.31) * 0.8).toFixed(2)); const high = Number((Math.max(open, close) + 0.3 + Math.abs(Math.sin(index)) * 0.7).toFixed(2)); const low = Number((Math.min(open, close) - 0.3 - Math.abs(Math.cos(index)) * 0.7).toFixed(2)); const prior = [...points.slice(Math.max(0, points.length - 19)).map((point) => point.price), close]; const sma20 = Number((prior.reduce((sum, value) => sum + value, 0) / prior.length).toFixed(2)); points.push({ label: new Date(start + index * interval * 60_000).toISOString(), price: close, open, high, low, volume: Math.round(280_000 + Math.abs(Math.sin(index / 3)) * 900_000), entryLevel: anchor, stopLevel: stop, targetLevel: target, sma20 }); } return points; }

function TradePlanWidget({ symbol, plan, setPlan, sizing, policy }: { symbol: string; plan: PlanState; setPlan: (value: PlanState | ((current: PlanState) => PlanState)) => void; sizing: ReturnType<typeof calculatePositionSizing>; policy: ReturnType<typeof evaluatePaperPolicy> }) { return <div className="space-y-3 p-3"><div className="flex items-center justify-between"><strong className="text-xs">{symbol}</strong><span className="text-[10px] text-[var(--text-muted)]">{plan.direction === "long" ? "Long" : "Short"} · {plan.timeInForce === "day" ? "Day" : "GTC"}</span></div><div className="flex rounded-lg bg-[var(--surface-control)] p-1" role="group" aria-label="Trade direction">{(["long", "short"] as const).map((direction) => <button key={direction} aria-pressed={plan.direction === direction} onClick={() => setPlan((current) => ({ ...current, direction }))} className={`h-8 flex-1 rounded-md border text-xs font-semibold capitalize ${plan.direction === direction ? "border-indigo-primary bg-[var(--surface-selected)]" : "border-transparent text-[var(--text-muted)]"}`}>{direction}</button>)}</div><div className="grid grid-cols-2 gap-2"><PlanSelect label="Order type" value={plan.orderType} options={[{ value: "market", label: "Market" }, { value: "limit", label: "Limit" }, { value: "stop", label: "Stop market" }]} onChange={(orderType) => setPlan((current) => ({ ...current, orderType: orderType as PlanState["orderType"] }))} /><PlanSelect label="Time in force" value={plan.timeInForce} options={[{ value: "day", label: "Day" }, { value: "gtc", label: "Good ’til canceled" }]} onChange={(timeInForce) => setPlan((current) => ({ ...current, timeInForce: timeInForce as PlanState["timeInForce"] }))} /></div><div className="grid grid-cols-3 gap-2"><PlanInput field="entry" label="Entry" plan={plan} setPlan={setPlan} sizing={sizing} /><PlanInput field="stop" label="Stop" plan={plan} setPlan={setPlan} sizing={sizing} /><PlanInput field="target" label="Target" plan={plan} setPlan={setPlan} sizing={sizing} /></div><PlanInput field="riskBudget" label="Risk budget ($)" plan={plan} setPlan={setPlan} sizing={sizing} /><div className="grid grid-cols-2 gap-3 border-y border-[var(--theme-border)] py-3"><Result label="Quantity" value={`${sizing.quantity} shares`} /><Result label="Capital required" value={money(sizing.capitalRequired)} /><Result label="Risk / share" value={money(sizing.riskPerShare)} /><Result label="Maximum loss" value={money(sizing.maximumLoss)} /><Result label="Reward / risk" value={sizing.rewardRiskRatio == null ? "Unavailable" : `${sizing.rewardRiskRatio.toFixed(2)} : 1`} /><Result label="Heat after" value={sizing.portfolioHeatAfter == null ? "Unavailable" : `${sizing.portfolioHeatAfter.toFixed(2)}%`} /></div><label className="block text-[10px] text-[var(--text-muted)]">Trade thesis or note<textarea aria-label="Trade thesis or note" value={plan.thesis} onChange={(event) => setPlan((current) => ({ ...current, thesis: event.target.value }))} rows={2} className="mt-1 w-full resize-none rounded-lg border border-[var(--theme-border-strong)] bg-[var(--surface-control)] p-2 text-xs" /></label><AlertDialog><AlertDialogTrigger render={<button type="button" disabled={policy.status === "failed"} className="theme-solid-action h-10 w-full rounded-lg text-xs font-semibold disabled:cursor-not-allowed disabled:opacity-35" />}>Review paper order</AlertDialogTrigger><ReviewContent symbol={symbol} plan={plan} sizing={sizing} policy={policy} /></AlertDialog></div>; }
function PlanSelect({ label, value, options, onChange }: { label: string; value: string; options: Array<{ value: string; label: string }>; onChange: (value: string) => void }) { const selected = options.find((option) => option.value === value)?.label ?? value; const testId = `${label.toLowerCase().replaceAll(" ", "-")}-options-menu`; return <div className="min-w-0 text-[10px] text-[var(--text-muted)]"><span>{label}</span><DropdownMenu><DropdownMenuTrigger render={<button type="button" aria-label={label} className="mt-1 flex h-9 w-full items-center justify-between rounded-lg border border-[var(--theme-border-strong)] bg-[var(--surface-control)] px-2 text-left text-xs text-[var(--text-primary)] outline-none focus-visible:ring-2 focus-visible:ring-indigo-primary/50" />}><span className="truncate">{selected}</span><ChevronDown className="size-3.5 shrink-0 text-[var(--text-subtle)]" /></DropdownMenuTrigger><DropdownMenuContent side="bottom" align="start" sideOffset={6} aria-label={`${label} options`} data-testid={testId} className="w-48 rounded-xl p-1.5">{options.map((option) => <DropdownMenuItem key={option.value} onClick={() => onChange(option.value)} className="h-9 rounded-lg px-2 text-xs"><span className="grid size-4 place-items-center">{option.value === value && <Check className="size-3.5" />}</span>{option.label}</DropdownMenuItem>)}</DropdownMenuContent></DropdownMenu></div>; }
function PlanInput({ field, label, plan, setPlan, sizing }: { field: "entry" | "stop" | "target" | "riskBudget"; label: string; plan: PlanState; setPlan: (value: PlanState | ((current: PlanState) => PlanState)) => void; sizing: ReturnType<typeof calculatePositionSizing> }) { const error = sizing.errors.find((item) => item.field === field); return <label className="min-w-0 text-[10px] text-[var(--text-muted)]">{label}<input type="number" inputMode="decimal" value={plan[field]} onChange={(event) => setPlan((current) => ({ ...current, [field]: event.target.value }))} aria-invalid={Boolean(error)} aria-describedby={error ? `${field}-error` : undefined} className="mt-1 h-9 w-full min-w-0 rounded-lg border border-[var(--theme-border-strong)] bg-[var(--surface-control)] px-2 text-xs tabular-nums outline-none focus:border-indigo-primary focus:ring-2 focus:ring-indigo-primary/20" />{error && <span id={`${field}-error`} className="mt-1 block text-[10px] leading-4 text-rose-400">{error.message}</span>}</label>; }
function Result({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] text-[var(--text-muted)]">{label}</p><p className="mt-1 text-xs font-semibold tabular-nums">{value}</p></div>; }

function PolicyCheckWidget({ policy }: { policy: ReturnType<typeof evaluatePaperPolicy> }) { return <div className="p-3"><div className={`mb-3 flex items-center gap-2 text-xs font-semibold ${policy.status === "failed" ? "text-rose-400" : "text-emerald-400"}`}>{policy.status === "failed" ? <AlertTriangle className="size-4" /> : <ShieldCheck className="size-4" />}{policy.status === "failed" ? "Policy blocked" : "Policy passed"}</div><div className="space-y-3">{policy.checks.map((check) => <div key={check.id} className="border-l-2 border-[var(--theme-border-strong)] pl-2"><p className="flex items-center gap-1.5 text-[11px] font-semibold">{check.status === "passed" ? <Check className="size-3.5 text-emerald-400" /> : check.status === "failed" ? <AlertTriangle className="size-3.5 text-rose-400" /> : <span aria-hidden>–</span>}{check.label}</p><p className="mt-1 text-[10px] leading-4 text-[var(--text-muted)]">{check.detail}</p></div>)}</div><p className="mt-3 border-t border-[var(--theme-border)] pt-2 text-[10px] text-[var(--text-subtle)]">Paper Trading policy defaults</p></div>; }

function TradingActivityWidget({ activeTab, setActiveTab, orders, symbol, summary }: { activeTab: ActivityTab; setActiveTab: (tab: ActivityTab) => void; orders: PaperOrder[]; symbol: string; summary: ReturnType<typeof usePortfolioBooks>["summary"] }) { const tabRefs = useRef<Array<HTMLButtonElement | null>>([]); const onKey = (index: number, key: string) => { if (key !== "ArrowLeft" && key !== "ArrowRight") return; const next = (index + (key === "ArrowRight" ? 1 : -1) + TABS.length) % TABS.length; setActiveTab(TABS[next]); tabRefs.current[next]?.focus(); }; return <div><div className="flex overflow-x-auto border-b border-[var(--theme-border)]" role="tablist" aria-label="Trading activity">{TABS.map((tab, index) => <button key={tab} ref={(node) => { tabRefs.current[index] = node; }} role="tab" aria-selected={activeTab === tab} tabIndex={activeTab === tab ? 0 : -1} onKeyDown={(event) => onKey(index, event.key)} onClick={() => setActiveTab(tab)} className={`h-10 shrink-0 px-3 text-[10px] font-semibold ${activeTab === tab ? "border-b-2 border-indigo-primary text-[var(--text-primary)]" : "text-[var(--text-muted)]"}`}>{tab}</button>)}</div><div role="tabpanel" aria-live="polite" className="p-3"><ActivityContent tab={activeTab} orders={orders} symbol={symbol} summary={summary} /></div></div>; }
function ActivityContent({ tab, orders, symbol, summary }: { tab: ActivityTab; orders: PaperOrder[]; symbol: string; summary: ReturnType<typeof usePortfolioBooks>["summary"] }) { if (tab === "Orders") return orders.length ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead className="text-[10px] uppercase text-[var(--text-subtle)]"><tr>{["Symbol", "Side", "Quantity", "Order type", "Entry", "Status", "Submitted", "Max risk"].map((label) => <th key={label} className="pb-2 pr-4">{label}</th>)}</tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-t border-[var(--theme-border)]"><td className="py-2 pr-4 font-semibold">{order.symbol}</td><td className="pr-4 capitalize">{order.side}</td><td className="pr-4">{order.quantity}</td><td className="pr-4 capitalize">{order.orderType ?? "market"} · {(order.timeInForce ?? "day").toUpperCase()} · Paper</td><td className="pr-4">{money(order.entry)}</td><td className="pr-4">{order.status}</td><td className="pr-4">{new Date(order.submittedAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</td><td>{money(order.maximumLoss)}</td></tr>)}</tbody></table></div> : <Empty text="No paper orders have been submitted in this session." />; if (tab === "Signals") return <p className="text-xs text-[var(--text-muted)]">Momentum setup active for {symbol}; no automatic order is enabled.</p>; if (tab === "Journal") return <p className="text-xs text-[var(--text-muted)]">Submitted simulated orders are summarized here and retained in the dedicated Decision Journal.</p>; if (tab === "Portfolio Risk") return <div className="grid gap-3 sm:grid-cols-3"><Result label="Recorded exposure" value={money(summary?.risk.gross_exposure ?? 0)} /><Result label="Trading allocation" value={`${(summary?.risk.trading_weight ?? 0).toFixed(1)}%`} /><Result label="Needs classification" value={String(summary?.risk.unclassified_count ?? 0)} /></div>; return <Empty text={tab === "Fills" ? "No simulated fills are open in this session." : "No open paper positions in this session."} />; }
function Empty({ text }: { text: string }) { return <p className="text-xs text-[var(--text-muted)]">{text}</p>; }

function ReviewContent({ symbol, plan, sizing, policy }: { symbol: string; plan: PlanState; sizing: ReturnType<typeof calculatePositionSizing>; policy: ReturnType<typeof evaluatePaperPolicy> }) { return <AlertDialogContent className="max-w-xl"><AlertDialogHeader><p className="text-xs font-semibold uppercase text-sky-300">Paper · illustrative</p><AlertDialogTitle>{plan.direction === "long" ? "Buy" : "Sell"} {sizing.quantity} {symbol}</AlertDialogTitle><AlertDialogDescription>This creates a session-scoped simulated order only. No live broker is connected.</AlertDialogDescription></AlertDialogHeader><ReviewSummary plan={plan} sizing={sizing} policy={policy} /><AlertDialogFooter><AlertDialogCancel autoFocus>Back to edit</AlertDialogCancel><AlertDialogAction form="paper-order-form" type="submit">Submit paper order</AlertDialogAction></AlertDialogFooter></AlertDialogContent>; }
function PaperOrderReview({ plan, sizing, policy, symbol, onSubmit }: { plan: PlanState; sizing: ReturnType<typeof calculatePositionSizing>; policy: ReturnType<typeof evaluatePaperPolicy>; symbol: string; onSubmit: () => Promise<void> }) { return <form id="paper-order-form" onSubmit={(event) => { event.preventDefault(); void onSubmit(); }} className="hidden" aria-hidden><input readOnly value={symbol} /></form>; }
function ReviewSummary({ plan, sizing, policy }: { plan: PlanState; sizing: ReturnType<typeof calculatePositionSizing>; policy: ReturnType<typeof evaluatePaperPolicy> }) { return <div className="mt-4 space-y-4"><div className="grid grid-cols-2 gap-3 sm:grid-cols-3"><Result label="Order" value={`${plan.orderType === "stop" ? "Stop market" : plan.orderType[0].toUpperCase() + plan.orderType.slice(1)} · ${plan.timeInForce.toUpperCase()}`} /><Result label="Entry" value={money(Number(plan.entry))} /><Result label="Stop" value={money(Number(plan.stop))} /><Result label="Target" value={money(Number(plan.target))} /><Result label="Quantity" value={String(sizing.quantity)} /><Result label="Estimated capital" value={money(sizing.capitalRequired)} /><Result label="Maximum loss" value={money(sizing.maximumLoss)} /><Result label="Reward / risk" value={`${(sizing.rewardRiskRatio ?? 0).toFixed(2)} : 1`} /><Result label="Portfolio heat" value={`${(sizing.portfolioHeatAfter ?? 0).toFixed(2)}%`} /></div><div className="border-t border-[var(--theme-border)] pt-3">{policy.checks.map((check) => <p key={check.id} className="mt-1 flex gap-2 text-xs text-[var(--text-muted)]">{check.status === "passed" ? <CheckCircle2 className="size-3.5 shrink-0 text-emerald-400" /> : check.status === "failed" ? <AlertTriangle className="size-3.5 shrink-0 text-rose-400" /> : <span className="w-3.5 text-center">–</span>} {check.detail}</p>)}</div>{plan.thesis.trim() && <div className="border-t border-[var(--theme-border)] pt-3"><p className="text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Trade thesis</p><p className="mt-1 text-xs leading-5 text-[var(--text-muted)]">{plan.thesis.trim()}</p></div>}</div>; }

function PresetMenu({ onSelect }: { onSelect: (template: TradingWorkspaceTemplate) => void }) { return <DropdownMenu><DropdownMenuTrigger render={<Button type="button" variant="outline" className="rounded-lg text-xs" />}><LayoutTemplate className="size-3.5" /> Presets</DropdownMenuTrigger><DropdownMenuContent side="bottom" align="end" aria-label="Workspace presets" data-testid="workspace-presets-menu" className="w-[44rem] rounded-xl p-3"><div className="mb-3"><p className="text-xs font-semibold">Workspace presets</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">Start a focused layout without changing paper-trading safety.</p></div><div className="grid grid-cols-2 gap-2">{WORKSPACE_TEMPLATES.map((template) => <DropdownMenuItem key={template.id} onClick={() => onSelect(template.id)} className="grid h-auto grid-cols-[7rem_minmax(0,1fr)] items-center gap-3 rounded-lg border border-[var(--theme-border)] p-2"><PresetMenuPreview template={template.id} /><span className="min-w-0"><strong className="block text-xs text-[var(--text-primary)]">{template.name}</strong><span className="mt-1 block text-[10px] leading-4 text-[var(--text-muted)]">{template.description}</span></span></DropdownMenuItem>)}</div></DropdownMenuContent></DropdownMenu>; }

function WidgetMenu({ widgets, onChoose }: { widgets: WorkspaceWidgetInstance[]; onChoose: (type: WorkspaceWidgetType) => void }) { return <DropdownMenu><DropdownMenuTrigger render={<Button type="button" variant="outline" className="rounded-lg text-xs" />}><Plus className="size-3.5" /> Add widget</DropdownMenuTrigger><DropdownMenuContent side="bottom" align="end" aria-label="Add widget menu" data-testid="add-widget-menu" className="w-[28rem] rounded-xl p-3"><div className="mb-3"><p className="text-xs font-semibold">Add widget</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">Choose one focused module for this workspace.</p></div><div className="grid grid-cols-2 gap-2">{Object.entries(workspaceWidgetRegistry).map(([type, item]) => { const instances = widgets.filter((widget) => widget.type === type); const hidden = instances.find((widget) => !widget.isVisible); const disabled = !item.allowDuplicate && instances.some((widget) => widget.isVisible); return <DropdownMenuItem key={type} disabled={disabled && !hidden} onClick={() => onChoose(type as WorkspaceWidgetType)} className="h-auto flex-col items-stretch gap-2 rounded-lg border border-[var(--theme-border)] p-2"><WidgetMiniature type={type as WorkspaceWidgetType} /><span className="flex items-center justify-between text-xs font-semibold text-[var(--text-primary)]"><span>{item.title}</span><span className="text-[10px] font-normal text-[var(--text-muted)]">{hidden ? "Restore" : disabled ? "Added" : "Add"}</span></span></DropdownMenuItem>; })}</div></DropdownMenuContent></DropdownMenu>; }

function EmptyTradingWorkspace({ onCreate, onAdd }: { onCreate: (template: TradingWorkspaceTemplate) => void; onAdd: (type: WorkspaceWidgetType) => void }) { return <section className="rounded-xl border border-dashed border-[var(--theme-border-strong)] bg-[var(--surface-card)] p-4 sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Empty trading workspace</p><h2 className="mt-1 font-heading text-xl font-semibold">Start from a template</h2><p className="mt-1 text-xs text-[var(--text-muted)]">Choose a complete paper layout or add only the tools you need.</p></div><span className="text-[10px] font-semibold uppercase text-[var(--text-subtle)]">Session safe · Illustrative</span></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{WORKSPACE_TEMPLATES.map((template) => <article key={template.id} className="overflow-hidden rounded-lg border border-[var(--theme-border)] bg-[var(--background)]"><TemplateMiniature template={template.id} compact /><div className="flex items-center justify-between gap-3 border-t border-[var(--theme-border)] p-3"><div className="min-w-0"><strong className="text-xs">{template.name}</strong><p className="mt-0.5 truncate text-[10px] text-[var(--text-muted)]">{template.description}</p></div><Button type="button" variant="outline" size="sm" onClick={() => onCreate(template.id)} className="shrink-0 rounded-lg text-xs">Use layout</Button></div></article>)}</div><div className="mt-5 border-t border-[var(--theme-border)] pt-4"><h3 className="text-sm font-semibold">Or add an individual widget</h3><div className="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{Object.entries(workspaceWidgetRegistry).map(([type, item]) => <button key={type} type="button" onClick={() => onAdd(type as WorkspaceWidgetType)} className="flex min-h-14 items-center gap-3 rounded-lg border border-[var(--theme-border)] bg-[var(--background)] p-2 text-left hover:bg-[var(--surface-card-hover)]"><div className="w-20 shrink-0"><WidgetMiniature type={type as WorkspaceWidgetType} /></div><span><strong className="block text-xs">{item.title}</strong><span className="mt-0.5 block text-[10px] text-[var(--text-muted)]">{item.description}</span></span></button>)}</div></div></section>; }

function PresetMenuPreview({ template, large = false }: { template: TradingWorkspaceTemplate; large?: boolean }) {
  const chart = (key: string) => <div key={key} className="relative min-w-0 overflow-hidden border border-[var(--theme-border)]"><svg viewBox="0 0 80 40" preserveAspectRatio="none" className="size-full"><path d="M0 32 L12 25 L23 29 L35 14 L48 21 L61 9 L80 15" fill="none" stroke="var(--color-cyan-secondary)" strokeWidth="2" vectorEffect="non-scaling-stroke" /></svg></div>;
  const list = (key: string) => <div key={key} className="space-y-1 overflow-hidden border border-[var(--theme-border)] p-1">{[70, 52, 62, 44].map((width) => <span key={width} className="block h-0.5 bg-[var(--theme-border-strong)]" style={{ width: `${width}%` }} />)}</div>;
  const form = (key: string) => <div key={key} className="grid grid-cols-3 gap-0.5 overflow-hidden border border-[var(--theme-border)] p-1">{[1, 2, 3].map((item) => <span key={item} className="h-2 border border-[var(--theme-border-strong)]" />)}<span className="col-span-3 h-1.5 bg-[var(--surface-selected)]" /></div>;
  const chain = (key: string) => <div key={key} className="grid grid-cols-5 gap-0.5 overflow-hidden border border-[var(--theme-border)] p-1">{Array.from({ length: 15 }, (_, index) => <span key={index} className={`h-1 ${index % 5 === 2 ? "bg-[var(--text-subtle)]" : index % 2 ? "bg-emerald-400/50" : "bg-rose-400/50"}`} />)}</div>;
  const shell = `${large ? "h-28 w-full p-2" : "h-16 w-28 p-1"} grid gap-0.5 overflow-hidden rounded-md bg-[var(--background)]`;
  if (template === "chart_spotlight") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[3fr_1fr]`}>{chart("chart")}<div className="grid gap-0.5">{list("watch")}{form("plan")}</div></div>;
  if (template === "market_monitor" || template === "watchlist_monitor" || template === "positions_monitor") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[1fr_3fr]`}>{list("side")}<div className="grid grid-cols-2 gap-0.5">{[1, 2, 3, 4].map((item) => chart(`chart-${item}`))}</div></div>;
  if (template === "positions_analysis") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[1fr_2fr]`}>{list("positions")}<div className="grid gap-0.5">{chart("chart")}<div className="grid grid-cols-2 gap-0.5">{form("plan")}{list("policy")}</div></div></div>;
  if (template === "advanced_options") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-rows-2`}><div className="grid grid-cols-[1fr_2fr] gap-0.5">{chart("chart")}{chain("chain")}</div><div className="grid grid-cols-3 gap-0.5">{list("orders")}{list("positions")}{list("account")}</div></div>;
  if (template === "options_trading") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[1fr_2fr_1fr]`}><div className="grid gap-0.5">{list("account")}{list("watch")}</div><div className="grid gap-0.5">{chart("chart")}{chain("chain")}</div><div className="grid gap-0.5">{list("positions")}{list("orders")}</div></div>;
  if (template === "stock_trading") return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[1fr_2fr_1fr]`}><div className="grid gap-0.5">{list("account")}{list("watch")}</div><div className="grid gap-0.5">{chart("chart")}{list("activity")}</div><div className="grid gap-0.5">{list("positions")}{list("orders")}</div></div>;
  return <div aria-hidden data-testid="preset-preview" className={`${shell} grid-cols-[1fr_2fr_1fr]`}><div className="grid gap-0.5">{list("watch")}{list("signals")}</div><div className="grid gap-0.5">{chart("chart")}{list("activity")}</div><div className="grid gap-0.5">{form("plan")}{list("policy")}</div></div>;
}

function TemplateMiniature({ template }: { template: TradingWorkspaceTemplate; compact?: boolean }) { return <PresetMenuPreview template={template} large />; }
function WidgetMiniature({ type }: { type: WorkspaceWidgetType }) {
  if (type === "price_chart") return <div aria-hidden className="relative h-20 overflow-hidden border border-[var(--theme-border)] bg-[var(--background)]"><svg viewBox="0 0 160 70" className="h-full w-full"><path d="M0 55 L18 47 L30 52 L45 34 L62 40 L78 22 L95 31 L112 17 L130 24 L160 8" fill="none" stroke="var(--color-cyan-secondary)" strokeWidth="2" /><path d="M0 44 H160 M0 22 H160" stroke="var(--theme-border)" /></svg></div>;
  if (type === "watchlist") return <div aria-hidden className="h-20 divide-y divide-[var(--theme-border)] border border-[var(--theme-border)] bg-[var(--background)] p-1">{["AMD", "NVDA", "AAPL"].map((symbol, index) => <div key={symbol} className="flex justify-between px-1 py-1 text-[8px]"><span>{symbol}</span><span className={index === 1 ? "text-rose-400" : "text-emerald-400"}>{index === 1 ? "▼ 0.7%" : "▲ 1.2%"}</span></div>)}</div>;
  if (type === "active_signals") return <div aria-hidden className="h-20 border border-[var(--theme-border)] bg-[var(--background)] p-2"><div className="flex gap-2"><Activity className="size-3 text-sky-300" /><div className="space-y-1"><div className="h-1.5 w-16 bg-[var(--text-muted)]" /><div className="h-1 w-20 bg-[var(--theme-border-strong)]" /><div className="h-1 w-14 bg-[var(--theme-border-strong)]" /></div></div></div>;
  if (type === "account") return <div aria-hidden className="h-20 border border-[var(--theme-border)] bg-[var(--background)] p-2"><div className="text-[8px] text-[var(--text-muted)]">Paper equity</div><div className="mt-1 text-xs font-semibold">$100,000</div><svg viewBox="0 0 100 30" className="mt-1 h-8 w-full"><path d="M0 24 L15 20 L28 22 L42 14 L58 18 L74 9 L100 4" fill="none" stroke="var(--color-green-positive)" strokeWidth="2" /></svg></div>;
  if (type === "options_chain") return <div aria-hidden className="grid h-20 grid-cols-5 gap-1 border border-[var(--theme-border)] bg-[var(--background)] p-2">{Array.from({ length: 20 }, (_, index) => <span key={index} className={`h-1 ${index % 5 === 2 ? "bg-[var(--text-subtle)]" : index % 2 ? "bg-emerald-400/60" : "bg-rose-400/60"}`} />)}</div>;
  if (type === "positions" || type === "recent_orders") return <div aria-hidden className="h-20 border border-[var(--theme-border)] bg-[var(--background)] p-2"><div className="grid grid-cols-3 gap-1 border-b border-[var(--theme-border)] pb-1 text-[7px]"><span>Symbol</span><span>{type === "positions" ? "Qty" : "Side"}</span><span>{type === "positions" ? "Risk" : "Status"}</span></div>{[1, 2, 3].map((row) => <div key={row} className="mt-1 grid grid-cols-3 gap-1"><span className="h-1 bg-[var(--theme-border-strong)]" /><span className="h-1 bg-[var(--theme-border-strong)]" /><span className={`h-1 ${row === 2 ? "bg-rose-400/50" : "bg-emerald-400/50"}`} /></div>)}</div>;
  if (type === "trade_plan") return <div aria-hidden className="grid h-20 grid-cols-3 gap-1 border border-[var(--theme-border)] bg-[var(--background)] p-2">{["170", "164", "182"].map((value) => <div key={value} className="grid h-7 place-items-center border border-[var(--theme-border)] text-[8px]">{value}</div>)}<div className="col-span-3 h-4 bg-[var(--surface-selected)]" /></div>;
  if (type === "policy_check") return <div aria-hidden className="h-20 space-y-2 border border-[var(--theme-border)] bg-[var(--background)] p-2">{[1, 2, 3].map((value) => <div key={value} className="flex items-center gap-2"><Check className="size-3 text-emerald-400" /><div className="h-1 w-20 bg-[var(--theme-border-strong)]" /></div>)}</div>;
  return <div aria-hidden className="h-20 border border-[var(--theme-border)] bg-[var(--background)] p-2"><div className="flex gap-2 border-b border-[var(--theme-border)] pb-1 text-[7px]"><span>Positions</span><span>Orders</span><span>Fills</span></div><div className="mt-2 space-y-1"><div className="h-1 w-full bg-[var(--theme-border-strong)]" /><div className="h-1 w-3/4 bg-[var(--theme-border-strong)]" /></div></div>;
}
function money(value: number) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number.isFinite(value) ? value : 0); }
